import { useCallback, useEffect, useRef, useState } from "react";

export function SearchBox({ search, debounceMs = 300, minChars = 2 }) {
  const [value, setValue] = useState("");
  const [results, setResults] = useState([]);
  const [phase, setPhase] = useState("idle");

  const timerRef = useRef(null);
  const latestRequestRef = useRef(null);

  const clearPendingDebounce = useCallback(() => {
    if (timerRef.current !== null) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  const cancelLatestRequest = useCallback(() => {
    const request = latestRequestRef.current;
    latestRequestRef.current = null;

    if (
      request?.state === "inFlight" &&
      !request.controller.signal.aborted
    ) {
      request.controller.abort();
    }
  }, []);

  const resetForShortQuery = useCallback(() => {
    clearPendingDebounce();
    cancelLatestRequest();
    setResults((current) => (current.length === 0 ? current : []));
    setPhase("idle");
  }, [cancelLatestRequest, clearPendingDebounce]);

  const startRequest = useCallback(
    (query, force = false) => {
      clearPendingDebounce();

      const latestRequest = latestRequestRef.current;
      if (
        !force &&
        latestRequest?.query === query &&
        (latestRequest.state === "inFlight" ||
          latestRequest.state === "success")
      ) {
        return;
      }

      const controller = new AbortController();
      const request = {
        query,
        controller,
        state: "inFlight",
      };

      latestRequestRef.current = request;

      if (
        latestRequest &&
        !latestRequest.controller.signal.aborted
      ) {
        latestRequest.controller.abort();
      }

      setPhase("searching");

      const isCurrentRequest = () =>
        latestRequestRef.current === request &&
        !controller.signal.aborted;

      const handleSuccess = (items) => {
        if (!isCurrentRequest()) {
          return;
        }

        request.state = "success";
        setResults(items);
        setPhase("success");
      };

      const handleFailure = (error) => {
        if (!isCurrentRequest()) {
          return;
        }

        if (error?.name === "AbortError") {
          request.state = "aborted";
          setPhase("idle");
          return;
        }

        request.state = "failed";
        setResults([]);
        setPhase("error");
      };

      let promise;
      try {
        promise = search(query, { signal: controller.signal });
      } catch (error) {
        handleFailure(error);
        return;
      }

      Promise.resolve(promise).then(handleSuccess, handleFailure);
    },
    [clearPendingDebounce, search]
  );

  useEffect(() => {
    return () => {
      clearPendingDebounce();
      cancelLatestRequest();
    };
  }, [cancelLatestRequest, clearPendingDebounce]);

  useEffect(() => {
    clearPendingDebounce();

    const query = value.trim();

    if (query.length < minChars) {
      resetForShortQuery();
      return undefined;
    }

    const timerId = setTimeout(() => {
      if (timerRef.current !== timerId) {
        return;
      }

      timerRef.current = null;
      startRequest(query);
    }, debounceMs);

    timerRef.current = timerId;

    return () => {
      clearTimeout(timerId);
      if (timerRef.current === timerId) {
        timerRef.current = null;
      }
    };
  }, [
    value,
    debounceMs,
    minChars,
    clearPendingDebounce,
    resetForShortQuery,
    startRequest,
  ]);

  const handleChange = (event) => {
    const nextValue = event.target.value;

    clearPendingDebounce();
    setValue(nextValue);

    if (nextValue.trim().length < minChars) {
      resetForShortQuery();
    }
  };

  const handleRetry = () => {
    clearPendingDebounce();

    const query = value.trim();
    if (query.length < minChars) {
      resetForShortQuery();
      return;
    }

    startRequest(query, true);
  };

  const statusText =
    phase === "searching"
      ? "Searching..."
      : phase === "success" && results.length === 0
        ? "No results"
        : "";

  return (
    <div>
      <input
        type="search"
        aria-label="Search"
        value={value}
        onChange={handleChange}
      />
      <div role="status">{statusText}</div>
      <ul aria-label="Results">
        {results.map((result, index) => (
          <li key={index}>{result}</li>
        ))}
      </ul>
      {phase === "error" && (
        <div role="alert">
          Something went wrong{" "}
          <button type="button" onClick={handleRetry}>
            Retry
          </button>
        </div>
      )}
    </div>
  );
}
